CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.meta_date(m jsonb, code text) RETURNS date
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $corps$
DECLARE
    v text := m ->> code;
    an int;
    mois int;
    jour int;
BEGIN
    IF v IS NULL OR v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
        RETURN NULL;
    END IF;
    an := substr(v, 1, 4)::int;
    mois := substr(v, 6, 2)::int;
    jour := substr(v, 9, 2)::int;
    -- Pas de bloc EXCEPTION (sous-transaction interdite en plan parallèle) :
    -- an 0000, mois 00 ou 13, 31 avril, 29 février non bissextile → NULL.
    -- (CASE entre parenthèses : sinon son premier THEN clôt la condition du IF.)
    IF an < 1 OR mois NOT BETWEEN 1 AND 12 OR jour < 1 OR jour > (CASE
            WHEN mois = 2 THEN CASE WHEN an % 4 = 0 AND (an % 100 <> 0 OR an % 400 = 0) THEN 29 ELSE 28 END
            WHEN mois IN (4, 6, 9, 11) THEN 30
            ELSE 31
        END) THEN
        RETURN NULL;
    END IF;
    RETURN make_date(an, mois, jour);
END
$corps$

CREATE OR REPLACE FUNCTION ${database.defaultSchemaName}.meta_nombre(m jsonb, code text) RETURNS numeric
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $corps$
DECLARE
    v text := m ->> code;
    p text[];
    entier text;
    fraction text;
    exposant bigint := 0;
BEGIN
    p := regexp_match(v, '^-?([0-9]+)(?:\.([0-9]+))?(?:[eE]([-+]?[0-9]+))?$');
    IF p IS NULL THEN
        RETURN NULL;
    END IF;
    -- Limites du type numeric vérifiées avant la conversion, qui sinon lève
    -- « value overflows numeric format » (et ferait échouer toute la requête).
    entier := ltrim(p[1], '0');
    fraction := coalesce(p[2], '');
    IF p[3] IS NOT NULL THEN
        IF length(ltrim(ltrim(p[3], '+-'), '0')) > 10 THEN
            RETURN NULL;
        END IF;
        exposant := coalesce(nullif(ltrim(ltrim(p[3], '+-'), '0'), ''), '0')::bigint;
        IF exposant > 1073741823 THEN
            RETURN NULL;
        END IF;
        IF left(p[3], 1) = '-' THEN
            exposant := -exposant;
        END IF;
    END IF;
    -- Échelle : 16 383 chiffres au plus après la virgule.
    IF length(fraction) - exposant > 16383 THEN
        RETURN NULL;
    END IF;
    -- Poids : 131 072 chiffres au plus avant la virgule (rang du premier chiffre significatif).
    IF entier <> '' THEN
        IF length(entier) + exposant > 131072 THEN
            RETURN NULL;
        END IF;
    ELSIF ltrim(fraction, '0') <> '' THEN
        IF exposant - (length(fraction) - length(ltrim(fraction, '0'))) > 131072 THEN
            RETURN NULL;
        END IF;
    END IF;
    RETURN v::numeric;
END
$corps$

